package com.oms.order.service;

import org.junit.jupiter.api.*;
import java.util.*;
import static com.oms.order.service.GiftRules.*;
import static com.oms.order.service.OrderValues.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class GiftStrategyDesignerTest {
    GiftStrategyDesigner designer;GiftService gifts;OrderCatalog catalog;
    @BeforeEach void setup(){
        catalog=mock(OrderCatalog.class);gifts=new GiftService();gifts.catalog=catalog;gifts.repository=mock(OrderRepository.class);gifts.inventory=mock(OrderWarehouseClient.class);gifts.cutoffs=mock(OrderCutoffService.class);
        designer=new GiftStrategyDesigner();designer.catalog=catalog;designer.gifts=gifts;
        when(catalog.goods(eq("DRAFT"),anyList())).thenAnswer(call->{Map<String,List<Map<String,Object>>> result=new HashMap<>();for(String sku:(List<String>)call.getArgument(1))if(!sku.equals("MISSING"))result.put(sku,Collections.singletonList(map("sku_sn",sku,"goods_name","商品"+sku,"color_name","白色","size_name","M","is_gift",sku.equals("NORMAL")?0:1,"is_fd",sku.equals("BAG")?1:0,"is_package",sku.equals("VIRTUAL")?1:0,"inventory_mode",sku.equals("VIRTUAL")?"VIRTUAL":"STOCKED")));return result;});
    }
    Map<String,Object> draft(){return map("name","草稿策略","policy",GiftRulesTest.policy(Arrays.asList(GiftRulesTest.rule("R1","AMOUNT",1,"100","G"),GiftRulesTest.rule("R2","MULTIPLE",2,"0","X"))),"paid_time","2026-10-20 12:00:00","lines",Collections.singletonList(map("sku_sn","A","quantity",4,"payment","400.00")));}
    @AfterEach void readOnly(){verifyNoInteractions(gifts.repository,gifts.inventory,gifts.cutoffs);}
    @Test void draftRunsProductionEvaluatorWithoutSavingOrOccupyingStock(){Map<String,Object> input=draft();String before=encode(input);Map<String,Object> result=designer.simulate("DRAFT",input);assertEquals(Boolean.TRUE,result.get("simulated"));assertEquals(2,rows(result.get("gifts")).size());assertEquals(2,number(rows(result.get("gifts")).get(1),"quantity"));assertEquals(before,encode(input));}
    @Test void unpaidRangeDoesNotGrantGifts(){Map<String,Object> input=draft();input.put("paid_time","2026-12-01 00:00:00");assertTrue(rows(designer.simulate("DRAFT",input).get("gifts")).isEmpty());}
    @Test void unsavedStopRuleControlsTrialPath(){Map<String,Object> input=draft();Map<String,Object> policy=object(input.get("policy"));List<Map<String,Object>> rules=rows(policy.get("rules"));rules.get(0).put("stop",true);policy.put("rules",rules);input.put("policy",policy);Map<String,Object> result=designer.simulate("DRAFT",input);assertEquals(1,rows(result.get("gifts")).size());assertEquals(Boolean.TRUE,rows(rows(result.get("trace")).get(0).get("rules")).get(1).get("skipped"));}
    @Test void bulkResolveExplainsInvalidAndUnsuitableGiftSkus(){List<Map<String,Object>> result=designer.resolve("DRAFT",map("skus",Arrays.asList("G","G","MISSING","BAG","VIRTUAL"),"use","GIFT"));assertEquals(4,result.size());assertEquals(Boolean.TRUE,result.get(0).get("valid"));assertEquals("白色 M",result.get(0).get("specs"));for(int i=1;i<4;i++)assertEquals(Boolean.FALSE,result.get(i).get("valid"));assertEquals(Boolean.TRUE,designer.resolve("DRAFT",map("skus",Collections.singletonList("VIRTUAL"),"use","PURCHASE")).get(0).get("valid"));}
    @Test void resolveIsBoundedAndRejectsMalformedOrUnknownUse(){assertThrows(IllegalArgumentException.class,()->designer.resolve("DRAFT",map("skus",Collections.emptyList(),"use","GIFT")));assertThrows(IllegalArgumentException.class,()->designer.resolve("DRAFT",map("skus",Collections.nCopies(201,"A"),"use","GIFT")));assertThrows(IllegalArgumentException.class,()->designer.resolve("DRAFT",map("skus",Collections.singletonList(1),"use","GIFT")));assertThrows(IllegalArgumentException.class,()->designer.resolve("DRAFT",map("skus",Collections.singletonList("G"),"use","OTHER")));}
    @Test void simulationUsesSameSkuAndPhysicalGiftChecksAsSave(){Map<String,Object> input=draft();Map<String,Object> p=GiftRulesTest.policy(Collections.singletonList(GiftRulesTest.rule("R1","PRODUCT",1,"0","VIRTUAL")));input.put("policy",p);assertThrows(IllegalArgumentException.class,()->designer.simulate("DRAFT",input));Map<String,Object> missing=draft();missing.put("lines",Collections.singletonList(map("sku_sn","MISSING","quantity",1,"payment","1")));assertThrows(IllegalArgumentException.class,()->designer.simulate("DRAFT",missing));}
    @Test void simulationRejectsDuplicateFractionalNegativeAndGiftPurchaseLines(){for(Map<String,Object> line:Arrays.asList(map("sku_sn","A","quantity",0,"payment","1"),map("sku_sn","A","quantity","1.5","payment","1"),map("sku_sn","A","quantity",1,"payment","-1"),map("sku_sn","A","quantity",1,"payment","0.001"),map("sku_sn","A","quantity",1,"payment","1","line_kind","GIFT"))){Map<String,Object> input=draft();input.put("lines",Collections.singletonList(line));assertThrows(IllegalArgumentException.class,()->designer.simulate("DRAFT",input));}Map<String,Object> duplicate=draft();duplicate.put("lines",Arrays.asList(map("sku_sn","A","quantity",1,"payment","1"),map("sku_sn","A","quantity",1,"payment","1")));assertThrows(IllegalArgumentException.class,()->designer.simulate("DRAFT",duplicate));}
    @Test void unknownCompanyCannotResolveOtherCompanyGoods(){when(catalog.goods(eq("OTHER"),anyList())).thenReturn(Collections.emptyMap());assertEquals(Boolean.FALSE,designer.resolve("OTHER",map("skus",Collections.singletonList("G"),"use","GIFT")).get(0).get("valid"));Map<String,Object> input=draft();assertThrows(IllegalArgumentException.class,()->designer.simulate("OTHER",input));}
    @Test void bulkAndDraftSimulationRejectUntaggedGiftWithoutRestrictingPurchaseSku(){
        assertEquals(Boolean.FALSE,designer.resolve("DRAFT",map("skus",Collections.singletonList("NORMAL"),"use","GIFT")).get(0).get("valid"));assertEquals(Boolean.TRUE,designer.resolve("DRAFT",map("skus",Collections.singletonList("NORMAL"),"use","PURCHASE")).get(0).get("valid"));Map<String,Object> input=draft();input.put("policy",GiftRulesTest.policy(Collections.singletonList(GiftRulesTest.rule("R1","PRODUCT",1,"0","NORMAL"))));assertThrows(IllegalArgumentException.class,()->designer.simulate("DRAFT",input));
    }
}
